17	import { compareToken } from '../../basics/token';
18	import { ValueObjectFactory } from '../value-object/array-value-object';
19	import type { BaseValueObject } from '../value-object/base-value-object';
20	
21	export function findCompareToken(str: string): [compareToken, BaseValueObject] {
22	    const comparisonTokens: compareToken[] = [
23	        compareToken.EQUALS,
24	        compareToken.NOT_EQUAL,
25	        compareToken.GREATER_THAN_OR_EQUAL,
26	        compareToken.GREATER_THAN,
27	        compareToken.LESS_THAN_OR_EQUAL,
28	        compareToken.LESS_THAN,
29	    ];
30	
31	    for (const token of comparisonTokens) {
32	        if (str.startsWith(token)) {
33	            const content = str.substring(token.length);
34	            return [token, ValueObjectFactory.create(content) as BaseValueObject];
35	        }
36	    }
37	
38	    return [compareToken.EQUALS, ValueObjectFactory.create(str) as BaseValueObject];
39	}
40	
41	/**
42	 * When it contains both comparison characters and wildcard characters
43	 * 1. The value of apple* has the same effect as =apple*
44	 * 2. >=apple*: normal value, >apple: obtains the same effect as >=apple*
45	 * 3. <apple*: normal value, <=apple: obtains the same effect as <apple*
46	 */
47	export function valueObjectCompare(range: BaseValueObject, criteria: BaseValueObject, operator?: compareToken) {
48	    if (!operator) {
49	        // Only strings can extract comparison symbols, other types of values are 'equal to'
50	        // TODO: criteria: 32, ">32", B5, "3?", "apple*", "*~?", TODAY(), ">"&A1:B3
51	        if (criteria.isString()) {
52	            const criteriaValueString = `${criteria.getValue()}`;
53	            const [token, criteriaStringObject] = findCompareToken(criteriaValueString);
54	            operator = token;
55	            criteria = criteriaStringObject;
56	        } else {
57	            operator = compareToken.EQUALS;
58	        }
59	    }
60	
61	    return range.compare(criteria, operator);
62	}
