23	export class Sumif extends BaseFunction {
24	    override calculate(range: BaseValueObject, criteria: BaseValueObject, sumRange?: BaseValueObject) {
25	        if (range.isError() || criteria.isError() || sumRange?.isError()) {
26	            return new ErrorValueObject(ErrorType.NA);
27	        }
28	
29	        if (!range.isArray() || (sumRange && !sumRange.isArray())) {
30	            return new ErrorValueObject(ErrorType.VALUE);
31	        }
32	
33	        if (criteria.isArray()) {
34	            return criteria.map((criteriaItem) => this._handleSingleObject(range, criteriaItem, sumRange));
35	        }
36	
37	        return this._handleSingleObject(range, criteria, sumRange);
38	    }
39	
40	    private _handleSingleObject(range: BaseValueObject, criteria: BaseValueObject, sumRange?: BaseValueObject) {
41	        const resultArrayObject = valueObjectCompare(range, criteria);
42	
43	        // sumRange has the same dimensions as range
44	        const sumRangeArray = sumRange
45	            ? (sumRange as ArrayValueObject).slice(
46	                [0, (range as ArrayValueObject).getRowCount()],
47	                [0, (range as ArrayValueObject).getColumnCount()]
48	            )
49	            : (range as ArrayValueObject);
50	
51	        if (!sumRangeArray) {
52	            return new ErrorValueObject(ErrorType.VALUE);
53	        }
54	
55	        return sumRangeArray.pick(resultArrayObject as ArrayValueObject).sum();
56	    }
