        if (valueObject2?.isError()) {
            return valueObject2;
        }

        if (valueObject1?.isBoolean() && valueObject2?.isBoolean()) {
            return new BooleanValueObject(valueObject1.getValue() && valueObject2.getValue());
        }

        return new BooleanValueObject(false);
    });
